-- road segments (only if the table is empty)
select * from (values
  ('Balakot → Kiwai', 'Riverside stretch along the Kunhar', 'open'::road_status, 0),
  ('Kiwai → Kaghan → Naran', 'Main N-15 section', 'open'::road_status, 1),
  ('Naran → Batakundi', 'Roadside waterfalls cross the road in places. Drive slowly', 'open'::road_status, 2),
  ('Batakundi → Babusar Top', 'Via Besal ford and Lulusar Lake', 'seasonal'::road_status, 3),
  ('Babusar Top → Chilas', 'Steep descent, check before going', 'seasonal'::road_status, 4)
) v where not exists (select 1 from public.road_segments);

update public.site_settings set alert_banner = 'Babusar Top is a seasonal pass. Check road status before driving beyond Batakundi.' where id = 1 and alert_banner = '';

commit;

