insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('balakot', 1, 'Balakot', 'بالاکوٹ', 'Gateway town', false, 980, 'Where the valley begins, on the Kunhar. The Kashmir and Kaghan roads split just above town.', 'https://commons.wikimedia.org/wiki/Special:FilePath/En%20route%20to%20Balakot.jpg?width=1600', '[{"name":"Country Club Walk Trail","note":"A walking trail at the start of Balakot.","isNew":true},{"name":"Hareem Waterfall","note":"On Naran Road, right next to Balakot.","isNew":true},{"name":"Balakot Hill Top","note":"First break point on the Kaghan road, where the routes to Kashmir and Kaghan split.","isNew":true},{"name":"Liaqat Bagh","note":"A park in town.","isNew":true},{"name":"Hadiyan","note":"Balakot’s upper viewpoint area.","isNew":true},{"name":"Syed Ahmad Shaheed Mosque & Tomb"},{"name":"Kaghan Valley Gate"},{"name":"Kunhar riverside viewpoints"}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('ghanool', 2, 'Ghanool', 'گھنول', 'Waterfall stop', false, null, 'About an hour’s drive from Balakot, for one of the valley’s newest waterfall finds.', 'https://commons.wikimedia.org/wiki/Special:FilePath/A%20waterfall%20in%20Naran.jpg?width=1600', '[{"name":"Ghanool Waterfall","note":"About 1 hour’s drive from Balakot.","isNew":true,"warning":"No shops or washrooms, and a landslide-prone area."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('kiwai', 3, 'Kiwai', 'کیوائی', 'Jeep junction', false, null, 'Park the car and switch to a local jeep for Shogran, after tea with your feet in the waterfall.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kunhar%20River%20in%20Naran%20Valley%20Richtone(HDR).jpg?width=1600', '[{"name":"Kiwai Waterfall","note":"Charpais and chairs set right in the water."},{"name":"Kiwai Village","note":"Park your car here and take a jeep up to Shogran."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('shogran', 4, 'Shogran', 'شوگران', 'Hill station', true, 2360, 'A forest hill station about 8 km above Kiwai, and the base for the Siri and Paye meadows.', 'https://commons.wikimedia.org/wiki/Special:FilePath/KaghanNaranShogran%201.jpg?width=1600', '[{"name":"Shogran","note":"About 8 km from Kiwai.","warning":"Rocky and steep road, so a local jeep is the better choice."},{"name":"Natural Park Shogran","note":"Forest walks and a picnic spot.","isNew":true},{"name":"Shogran Forest Rest House"},{"name":"Siri Meadows & Siri Lake","note":"4x4 jeeps only."},{"name":"Paye Meadows","note":"About 45 minutes by jeep from Shogran. Best to arrive before 2 pm."},{"name":"Makra Peak","note":"Trek from Paye. One visitor did 10 km in about 3.5 hours."},{"name":"Musa ka Musalla & Malika Parbat views"},{"name":"Shogran to Sharan hiking track"}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('paras-sharan', 5, 'Paras & Sharan', 'پارس اور شاران', 'Forest', true, null, 'A bridge over the Kunhar, then a 45-minute jeep ride up into the Sharan forest.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Montane%20meadow%20in%20Naran%20Valley%202017-01-19.jpg?width=1600', '[{"name":"Paras Bridge, Hangrai","note":"A bridge over the Kunhar near Paras.","isNew":true},{"name":"Sharan Forest","note":"About 45 min by jeep from Paras. Stays at the forest edge have Wi-Fi and Mobilink signal. Two youth hostels about 30 min further in have no mobile internet."},{"name":"Sharan Waterfall","note":"45 minutes to 1 hour from the camping pods.","warning":"The climb back is hard, but horses are available."},{"name":"Manshi Top","note":"3 to 4 hour hike from Sharan, with views of Musa ka Musalla, Shogran, Siri, Paye and Makra."},{"name":"Musa ka Musalla trek","note":"A 2 to 3 day trek from Sharan."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('malakandi', 6, 'Malakandi', 'ملکنڈی', 'National park', false, null, 'A young national park of forest and hiking trails.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khanian.jpg?width=1600', '[{"name":"Malakandi National Park","note":"Established 2022. A forest and hiking area between Paras, Bhoonja and Jared.","isNew":true}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('shinu-jared', 7, 'Shinu & Jared', 'شینو اور جرید', 'Trout & crafts', false, null, 'Pick your own trout for lunch, then shop for walnut-wood crafts.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Handicraft%20of%20Naran.jpg?width=1600', '[{"name":"Government Shinu Trout Hatchery","note":"Watch the trout breeding, buy a live trout and have it cooked at the restaurant opposite."},{"name":"Jared","note":"Walnut-wood furniture and handicrafts."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('mahandri-manoor', 8, 'Mahandri & Manoor', 'مہاندری اور منور', 'Bazaar & valley', false, null, 'The last good shopping stop before Naran, and the turn-off into the quiet Manoor Valley.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Herds%20of%20sheep%20going%20to%20high%20planes%20for%20summer%20seasons%20in%20Naran%2C%20KPK%2C%20Pakistan.jpg?width=1600', '[{"name":"Mahandri Bazaar","note":"A small riverside bazaar, and the last good place to shop before Naran.","isNew":true},{"name":"Beyari / Biari Village","note":"In Manoor Valley. Few visitors make it here.","isNew":true},{"name":"Rewri Cricket Ground","note":"A camping site in Manoor Valley.","isNew":true},{"name":"Manoor Biari Forest Rest House","note":"Book in advance.","isNew":true,"warning":"Ask locals about road conditions before you go."},{"name":"Kuch Gali & Manoor Peak","note":"Trekking routes from Mahandri."},{"name":"Ansoo Lake, alternative route","note":"A second way up to Ansoo, starting from Mahandri."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('khanian', 9, 'Khanian', 'کھنیاں', 'Trailhead', false, null, 'Resort trails and a long hike up to the Danna Meadows.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khanian.jpg?width=1600', '[{"name":"Hiking trail by Spruce Resort","isNew":true},{"name":"Danna Meadows","note":"2 to 6 hour trek from Khanian. The old jeep track was destroyed in the 2005 earthquake.","isNew":true,"warning":"No facilities, so carry water and food."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('kaghan', 10, 'Kaghan', 'کاغان', 'Valley town', false, 2050, 'The town the valley is named after: a bazaar, riverside resorts and two big viewpoints.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaghan%20and%20Naran%20Valleys.jpg?width=1600', '[{"name":"Kaghan Bazaar"},{"name":"Maidan Meadows","note":"Jeep from Kaghan Bazaar. The view from the top is superb.","isNew":true,"warning":"The jeep track is dangerous."},{"name":"Shingri Top","note":"About 2 km hike near Kaghan, to a mountain viewpoint.","isNew":true},{"name":"Riverside resorts","note":"Such as Luna Resort, between Kaghan and Naran."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('naran-picnic-point', 11, 'Naran Picnic Point', 'ناران پکنک پوائنٹ', 'Before Naran', false, null, 'A riverside pause just before town.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kunhar%20River%20in%20Naran%20Valley%20Richtone(HDR).jpg?width=1600', '[{"name":"Naran Picnic Point","note":"A viewpoint on the Kunhar.","isNew":true}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('naran', 12, 'Naran', 'ناران', 'Main base', false, 2400, 'The heart of the valley: bazaar, rafting, the legend caves and the jeep up to Saif-ul-Malook.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Naraan%20drone%20shot.jpg?width=1600', '[{"name":"Naran Bazaar & Kunhar River"},{"name":"Naran River Rafting Point","note":"2 km from Naran.","isNew":true},{"name":"Cave Naran Princess","note":"Small cave in town, opposite the Saif-ul-Malook road near Markhoor Hotel. About 12 ft deep, tied to the fairy-and-giant legend.","isNew":true},{"name":"Rose Park","note":"A park in Naran.","isNew":true},{"name":"Saif-ul-Malook Lake & National Park","note":"By jeep from Naran."},{"name":"Saif-ul-Malook Cave","note":"The original legend cave, beside the lake."},{"name":"Kach Gali","note":"Just beyond Saif-ul-Malook, recommended by a visitor.","isNew":true},{"name":"Ansoo Lake","note":"Trek from Saif-ul-Malook, about 10 hours return.","warning":"Don’t start after 9 am. Two streams to cross, so a horse is better."},{"name":"Malika Parbat"},{"name":"Lalazar to Saif-ul-Malook trek"},{"name":"Fairy Land & Baby Saral Lake","note":"Near Naran. Ask locally for the way."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('batakundi', 13, 'Batakundi', 'بٹہ کنڈی', 'Naran → Batakundi', false, null, 'Roadside waterfalls on the way, then the jeep track up to Lalazar. Batakundi is about 16 km from Naran.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lalzar%20view%20Naran.JPG?width=1600', '[{"name":"Kiswah Waterfall","note":"Water flows across the road.","isNew":true,"warning":"Drive slowly here."},{"name":"Sohni Waterfall","note":"Falls over step-like rocks. You can climb 50 to 60 ft to the water.","isNew":true},{"name":"Batakundi","note":"About 16 km from Naran. The Satsar Mala trek also starts from the campground."},{"name":"Lalazar","note":"Half-hour jeep from Batakundi. Old Dak Bungalow and a small forest at the top.","warning":"Dusty or slippery track."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('burawai', 14, 'Burawai', 'بوڑاوائی', 'Village', false, null, 'A small village with river views.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grazing%20horses%20of%20Naran.JPG?width=1600', '[{"name":"Burawai","note":"A small village with river views."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('jalkhad', 15, 'Jalkhad', 'جلکھڈ', 'Junction', false, null, 'Where the Sharda road meets the N-15, with views of Pyala Lake, Noori Top and Tiger Peak.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Land%20Of%20Fairies%20-%20Jalkhad.jpg?width=1600', '[{"name":"Jalkhad View Point","note":"Where the Sharda road meets N-15. Views of Pyala Lake, the Noori Top track and Tiger Peak (Mini K-2).","isNew":true},{"name":"Pyala Lake","note":"Right by the road, on the right before Besal.","warning":"No safety fence, so watch children."},{"name":"Noori Top","note":"Off-road jeep track from Jalkhad, continuing to Sharda (Neelum).","warning":"No hotels or food. Go in daylight only."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('besal', 16, 'Besal', 'بیسل', 'Trailhead', false, null, 'The start of the Dudipatsar trek, at Moon Restaurant.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Enroute%20Dodipatsar%20Lake%2C%20Naran%20Valley.jpg?width=1600', '[{"name":"Besal Ford","note":"A water crossing on the road.","isNew":true,"warning":"Take care in rain, especially on a motorbike."},{"name":"Moon Restaurant","note":"The Dudipatsar trek starts here."},{"name":"Hidden meadow & stream","note":"15-minute walk from Moon Restaurant, with green grass and a stream.","isNew":true},{"name":"Mullah ki Basti","note":"First camp on the Dudipatsar trek, about 8 hours from Besal."},{"name":"Dudipatsar Lake","note":"About 2 hours from Mullah ki Basti the next morning."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('lulusar', 17, 'Lulusar', 'لولوسر', 'Lake', false, 3410, 'A long, quiet lake by the road, with treks to higher lakes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stunning%20-%20Lulusar%20Lake.jpg?width=1600', '[{"name":"Lulusar Lake Viewpoint","note":"No boating allowed, so it stays peaceful."},{"name":"Lulusar Valley","note":"At the far end of the lake. The Abhom Pass trek is mentioned from here.","isNew":true},{"name":"Surkhail & Satsar Lakes","note":"A trek up above Lulusar."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('gittidas', 18, 'Gittidas', 'گٹی داس', 'Meadows', false, null, 'High roadside meadows with a glacier.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Montane%20meadow%20in%20Naran%20Valley%202017-01-19.jpg?width=1600', '[{"name":"Gittidas Meadows","note":"Roadside, with a glacier too."},{"name":"Satsar Mala trek","note":"Starts a little before Gittidas."}]'::jsonb)
insert into public.stops (slug, sort_order, name, name_ur, kind, side_trip, altitude, description, image_url, places) values ('babusar-top', 19, 'Babusar Top', 'بابوسر ٹاپ', 'Pass', false, 4173, 'The top of the valley, with a zipline and big views. Jeep tracks lead to Dharamsar Lake just before the pass.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lulosar%2CNaran%20Valley.jpg?width=1600', '[{"name":"Dharamsar Lake","note":"Jeep track just before Babusar Top, 1.5 to 3 hrs from the main road. Best to hire a 4x4 from Jalkhad."},{"name":"Sambaksar Lake","note":"About a 1-hour trek from Dharamsar, also visible from Babusar Top."},{"name":"Kalabashi Top","note":"On the route from Dharamsar to Mullah ki Basti."},{"name":"Babusar Top","note":"4,173 m, with a zipline and views."}]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('hotel', 'Hotel / Resort', 'Stay', 'BedDouble', 'Hotels, resorts and motels with rooms to rent.', false, false, '[{"key":"rooms","label":"Number of rooms","type":"number","required":true},{"key":"roomTypes","label":"Room types","type":"multiselect","options":["Standard","Deluxe","Family","Suite","Dormitory"]},{"key":"amenities","label":"Amenities","type":"multiselect","options":["Parking","Hot water","Heating","Wi-Fi","Generator / solar","Restaurant","River view","Family friendly"]},{"key":"checkIn","label":"Check-in time","type":"text","placeholder":"e.g. 12:00"},{"key":"season","label":"Open season","type":"select","options":["All year","Summer only (May to Oct)","Custom"]}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"registration","label":"Business registration or tourism licence","required":false,"hint":"Speeds up approval and earns a Verified badge."},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Room rates displayed","Safety: fire extinguisher / exits"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('guest-house', 'Guest house / Homestay', 'Stay', 'Home', 'Family-run guest houses and homestays.', false, false, '[{"key":"rooms","label":"Rooms","type":"number","required":true},{"key":"meals","label":"Meals included","type":"boolean"},{"key":"amenities","label":"Amenities","type":"multiselect","options":["Parking","Hot water","Heating","Wi-Fi","Family friendly"]}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('camping', 'Camping site', 'Stay', 'Tent', 'Campsites, camping pods and glamping.', false, false, '[{"key":"capacity","label":"Tents / pods available","type":"number","required":true},{"key":"facilities","label":"Facilities","type":"multiselect","options":["Washrooms","Tents provided","Bonfire","Food","Electricity","Security"]}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Washroom facilities verified","Site not in a landslide / flood zone"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('restaurant', 'Restaurant / Dhaba', 'Eat & shop', 'UtensilsCrossed', 'Restaurants, dhabas, tea stalls and BBQ.', false, false, '[{"key":"cuisine","label":"Cuisine","type":"multiselect","options":["Desi","BBQ","Trout","Chinese","Fast food","Tea & snacks"]},{"key":"seating","label":"Seating capacity","type":"number"},{"key":"hours","label":"Opening hours","type":"text","placeholder":"e.g. 8am to 11pm"},{"key":"familyArea","label":"Family area","type":"boolean"}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"food","label":"Food safety licence","required":false},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Menu with prices provided","Kitchen hygiene photos reviewed"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('shop', 'Shop / Store', 'Eat & shop', 'Store', 'General stores, handicrafts, outdoor gear, pharmacies.', false, false, '[{"key":"category","label":"Shop category","type":"select","options":["General store","Handicrafts","Outdoor gear","Clothing","Pharmacy","Mobile & SIM","Other"],"required":true},{"key":"hours","label":"Opening hours","type":"text"}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('jeep-operator', 'Jeep / Transport', 'Get around', 'CarFront', 'Jeep owners and drivers, car hire, transport services.', false, false, '[{"key":"vehicles","label":"Number of vehicles","type":"number","required":true},{"key":"vehicleModel","label":"Vehicle model(s)","type":"text","placeholder":"e.g. Willys 4x4"},{"key":"routes","label":"Routes served","type":"multiselect","options":["Naran → Saif-ul-Malook","Kiwai → Shogran","Shogran → Paye","Batakundi → Lalazar","Jalkhad → Noori Top","Dharamsar Lake","Kaghan → Maidan Meadows","Paras → Sharan"]},{"key":"seats","label":"Seats per vehicle","type":"number"}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"license","label":"Driving licence","required":true},{"key":"vehicleReg","label":"Vehicle registration","required":true},{"key":"vehiclePhotos","label":"Vehicle photos","required":true}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Driving licence valid","Vehicle registration matches","Vehicle roadworthy (photos)"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('tour-guide', 'Tour guide (individual)', 'People', 'UserRoundCheck', 'Individual local guides, trek leaders and porters.', true, false, '[{"key":"languages","label":"Languages spoken","type":"multiselect","options":["Urdu","English","Hindko","Pashto","Punjabi","Gojri","Shina"],"required":true},{"key":"areas","label":"Areas you guide","type":"multiselect","options":["Naran","Saif-ul-Malook & Ansoo","Shogran, Siri & Paye","Sharan & Manshi Top","Dudipatsar","Lulusar & Babusar","Manoor Valley","Musa ka Musalla"],"required":true},{"key":"experience","label":"Years of experience","type":"number","required":true},{"key":"dailyRate","label":"Daily rate (PKR)","type":"number"},{"key":"firstAid","label":"First-aid trained","type":"boolean"}]'::jsonb, '[{"key":"cnic","label":"CNIC (front & back)","required":true},{"key":"photo","label":"Profile photo","required":true},{"key":"guideLicence","label":"Guide licence or certificate","required":false,"hint":"Earns a Licensed Guide badge."},{"key":"reference","label":"Reference letter (hotel / tour company)","required":false}]'::jsonb, '["Phone number answered","CNIC matches applicant","Interview / call completed","References checked","Areas & experience plausible"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('tour-company', 'Tour company', 'People', 'Map', 'Registered tour operators and travel agencies.', false, false, '[{"key":"packages","label":"Package types","type":"multiselect","options":["Day trips","2 to 3 day tours","Treks","Family tours","Honeymoon","Corporate"]},{"key":"office","label":"Office location","type":"text"}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"registration","label":"Company registration (SECP / DTS)","required":true},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Company registration verified"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('adventure', 'Adventure activity', 'Adventure', 'MountainSnow', 'Zip lines, rafting, paragliding, horse riding, ATVs.', false, false, '[{"key":"activity","label":"Activity","type":"select","options":["Zip line","River rafting","Paragliding","Horse riding","ATV / quad bikes","Rock climbing","Fishing","Other"],"required":true},{"key":"minAge","label":"Minimum age","type":"number"},{"key":"safetyGear","label":"Safety gear provided","type":"multiselect","options":["Helmets","Harness","Life jackets","First-aid kit","Trained staff"]}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"safety","label":"Safety certificate / equipment inspection","required":true},{"key":"insurance","label":"Insurance (if any)","required":false},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant","Safety certificate valid","Equipment inspected (photos/video)","Staff trained"]'::jsonb)
insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('health', 'Clinic / Health centre', 'Services', 'Cross', 'Hospitals, BHUs, clinics and pharmacies.', false, true, '[{"key":"facility","label":"Facility type","type":"select","options":["Hospital","BHU / RHC","Private clinic","Pharmacy"]},{"key":"emergency","label":"24-hour emergency","type":"boolean"}]'::jsonb, '[]'::jsonb, '["Phone number answered","Location confirmed on map"]'::jsonb)
