insert into public.business_types (slug, name, grp, icon, description, individual, admin_only, fields, documents, checklist) values ('fuel', 'Fuel / Mechanic', 'Services', 'Fuel', 'Petrol pumps, tyre shops, mechanics and towing.', false, false, '[{"key":"services","label":"Services","type":"multiselect","options":["Petrol","Diesel","Tyre repair","Mechanic","Towing"]}]'::jsonb, '[{"key":"cnic","label":"Owner CNIC (front & back)","required":true,"hint":"Clear photo or scan. Only staff can see this."},{"key":"photos","label":"Photos of the premises","required":true,"hint":"At least 3 recent photos."}]'::jsonb, '["Phone number answered","Location confirmed on map","Photos are real and recent","Owner CNIC matches applicant"]'::jsonb)
